import { cacheTag, cacheLife } from 'next/cache'
import { getAllProducts } from './db'

export type Product = {
  id: number
  name: string
  price: number
}

// Single cached read path for catalog data. Every view that renders the
// catalog should go through this function so the "products" tag covers them
// all and a single sync invalidates everything consistently.
export async function getProducts(): Promise<Product[]> {
  'use cache'
  cacheTag('products')
  // Catalog data only changes when an upstream sync lands, so keep it cached
  // until the "products" tag is revalidated rather than on a timer.
  cacheLife('max')

  return getAllProducts()
}

